<template><div class="page-view"><div class="welcome-row"><div><h1>Projetos</h1><p class="subcopy">Acompanhe o progresso e as entregas de cada iniciativa.</p></div><button v-if="admin" class="primary-btn" @click="$emit('add')"><Plus/>Novo projeto</button></div><div class="project-cards"><button v-for="(p,index) in projects" :key="p.id" class="project-card" @click="$emit('open',p.id)"><div class="project-top"><span :class="['project-icon','p'+index%3]"><FolderKanban/></span><span class="open-arrow">→</span></div><h3>{{p.name}}</h3><p>{{p.description}}</p><div class="progress-label"><span>{{done(p.id)}} de {{total(p.id)}} concluídas</span><strong>{{progress(p.id)}}%</strong></div><div class="bar"><i :style="{width:progress(p.id)+'%',background:p.color}"/></div><div class="members"><small>Prazo: {{fmt(p.due)}}</small></div></button></div></div></template>
<script setup lang="ts">import{FolderKanban,Plus}from"lucide-vue-next";import type{Project,Task}from"../stores/taskflow";const props=defineProps<{projects:Project[];tasks:Task[];admin:boolean}>();defineEmits(["open","add"]);const total=(id:number)=>props.tasks.filter(t=>t.projectId===id).length,done=(id:number)=>props.tasks.filter(t=>t.projectId===id&&t.status==="Concluída").length,progress=(id:number)=>total(id)?Math.round(done(id)/total(id)*100):0,fmt=(v:string)=>new Intl.DateTimeFormat("pt-BR",{day:"2-digit",month:"short"}).format(new Date(v+"T12:00:00"));</script>
